#include <iostream>

// Prototype declarations
int cube(int y);
double calculateRunningAverage(double val);

int main() {
    for (int x = 1; x <= 4; ++x) {
        std::cout << "cube(" << x << ") = " << cube(x) << "\n";
    }

    std::cout << "Avg after 10.0: " << calculateRunningAverage(10.0) << "\n";
    std::cout << "Avg after 20.0: " << calculateRunningAverage(20.0) << "\n";
    std::cout << "Avg after 30.0: " << calculateRunningAverage(30.0) << "\n";
    return 0;
}

int cube(int y) {
    return y * y * y;
}

double calculateRunningAverage(double val) {
    static double total{0.0};
    static int count{0};

    total += val;
    ++count;
    return total / count;
}

#include <iostream>
#include <iomanip>
#include <cmath>

double calculateCharges(double hours) {
    if (hours <= 3.0) {
        return 2.00;
    }
    double charge = 2.00 + std::ceil(hours - 3.0) * 0.50;
    return (charge > 10.00) ? 10.00 : charge;
}

int main() {
    const double hours1 = 1.5;
    const double hours2 = 4.0;
    const double hours3 = 24.0;

    double charge1 = calculateCharges(hours1);
    double charge2 = calculateCharges(hours2);
    double charge3 = calculateCharges(hours3);

    double totalHours = hours1 + hours2 + hours3;
    double totalCharges = charge1 + charge2 + charge3;

    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Car      Hours       Charge\n";

    std::cout << std::setprecision(1);
    std::cout << "1" << std::setw(12) << hours1 << std::setw(13) << std::setprecision(2) << charge1 << "\n";
    std::cout << "2" << std::setw(12) << std::setprecision(1) << hours2 << std::setw(13) << std::setprecision(2) << charge2 << "\n";
    std::cout << "3" << std::setw(12) << std::setprecision(1) << hours3 << std::setw(13) << std::setprecision(2) << charge3 << "\n";
    std::cout << "TOTAL" << std::setw(8) << std::setprecision(1) << totalHours << std::setw(13) << std::setprecision(2) << totalCharges << "\n";

    return 0;
}
